def design(feats):
    X = np.asarray(feats.x, float); y = np.asarray(feats.y, float); n, p = X.shape
    ids = list(feats.ids); labs = sorted(set(feats.stratum))
    S = np.column_stack([np.ones(n)] + [np.array([s == l for s in feats.stratum], float) for l in labs[1:]])
    R = np.corrcoef(X, rowvar=False); R = np.nan_to_num(R)
    def ll(cols):
        Z = np.column_stack([S] + cols) if cols else S
        b = np.zeros(Z.shape[1])
        for _ in range(30):
            eta = np.clip(Z @ b, -30, 30); m = 1 / (1 + np.exp(-eta)); w = m * (1 - m) + 1e-9
            H = Z.T @ (Z * w[:, None]) + 1e-6 * np.eye(Z.shape[1])
            step = np.linalg.solve(H, Z.T @ (y - m)); b += step
            if np.abs(step).max() < 1e-7: break
        m = np.clip(1 / (1 + np.exp(-np.clip(Z @ b, -30, 30))), 1e-12, 1 - 1e-12)
        return float(np.sum(y * np.log(m) + (1 - y) * np.log(1 - m)))
    col = lambda j: X[:, j]
    sel = []; base = ll([])
    gates = [0.05 / p, 0.01 / p, 0.01 / p, 0.01 / p, 0.01 / p]
    for g in gates[:MAX_DRIVERS]:
        cur = [col(j) for j in sel]; best = None
        for j in range(p):
            if j in sel or any(abs(R[j, k]) >= 0.6 for k in sel): continue
            lr = 2 * (ll(cur + [col(j)]) - base)
            if best is None or lr > best[0]: best = (lr, j)
        if best is None or stats.chi2.sf(best[0], 1) > g: break
        j = best[1]
        clus = [k for k in range(p) if k not in sel and abs(R[j, k]) >= 0.6 and not any(abs(R[k, s]) >= 0.6 for s in sel)]
        if len(clus) > 1:
            gain = {k: ll(cur + [col(k)]) for k in clus}
            near = [k for k in clus if gain[k] >= gain[j] - 2]
            if len(near) > 1:
                def leftover(k):
                    l0 = gain[k]
                    return sum(ll(cur + [col(k), col(o)]) - l0 for o in clus if o != k)
                j = min(near, key=leftover)
        sel.append(j); base = ll([col(k) for k in sel])
    changed = True
    while changed and sel:
        changed = False; full = ll([col(k) for k in sel])
        for k in list(sel):
            red = ll([col(o) for o in sel if o != k])
            if stats.chi2.sf(2 * (full - red), 1) > 0.01 / p:
                sel.remove(k); changed = True; break
    cur = [col(k) for k in sel]; l0 = ll(cur)
    Zs = np.column_stack([S] + cur) if cur else S
    b = np.linalg.lstsq(Zs, y, rcond=None)[0]; r = y - np.clip(Zs @ b, 0.01, 0.99)
    pairs = [(a, c) for a in range(p) for c in range(a, p)]
    P = np.stack([X[:, a] * X[:, c] for a, c in pairs], 1)
    P = P - P.mean(0); sc = (r @ P) ** 2 / (np.sum(P ** 2, 0) + 1e-9)
    alpha = 0.01 / len(pairs); prods = []; used = set()
    for t in np.argsort(-sc)[:15]:
        a, c = pairs[t]
        if len(prods) >= 2 or a in used or c in used: continue
        mains = [col(a)] + ([col(c)] if c != a else [])
        lm = ll(cur + mains); lp = ll(cur + mains + [X[:, a] * X[:, c]])
        if stats.chi2.sf(2 * (lp - lm), 1) < alpha / (1 + 4 * len(prods)):
            prods.append((a, c)); used |= {a, c}; cur = cur + mains; l0 = lp
    drivers = list(sel)
    for a, c in prods:
        for k in (a, c):
            if k not in drivers: drivers.append(k)
    drivers = drivers[:MAX_DRIVERS]
    colset = sorted(set(sel) | {k for pr in prods for k in pr})
    return Design(drivers=tuple(ids[k] for k in drivers), columns=tuple(ids[k] for k in colset),
                  products=tuple((ids[a], ids[c]) for a, c in prods), loadings={})

